-- Phase 41: advanced KDS extends orders/order_items and kitchen_tickets. No parallel order system.
alter table public.plans add column if not exists advanced_kds_enabled boolean not null default false;
alter table public.plans add column if not exists kitchen_orchestration_enabled boolean not null default false;
alter table public.plans add column if not exists smart_kitchen_queue_enabled boolean not null default false;
alter table public.plans add column if not exists kitchen_batching_enabled boolean not null default false;
alter table public.plans add column if not exists kitchen_capacity_enabled boolean not null default false;
alter table public.store_feature_flags add column if not exists advanced_kds_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists kitchen_orchestration_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists smart_kitchen_queue_enabled boolean not null default false;
alter table public.store_feature_flags add column if not exists kitchen_batching_enabled boolean not null default false;
alter table public.store_feature_flags add column if not exists kitchen_capacity_enabled boolean not null default true;

create table public.kitchen_stations(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,
 name text not null,code text not null,station_type text not null default 'custom',active boolean not null default true,display_order integer not null default 0,capacity_config jsonb not null default '{"concurrent_tasks":1}',paused_at timestamptz,paused_reason text,
 created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(store_id,code)
);
create table public.product_station_assignments(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,
 product_id uuid not null references public.products(id) on delete cascade,variation_id uuid,station_id uuid not null references public.kitchen_stations(id) on delete cascade,preparation_sequence integer not null default 1 check(preparation_sequence>0),estimated_prep_time integer not null default 10 check(estimated_prep_time>0),primary_station boolean not null default true,active boolean not null default true,created_at timestamptz not null default now(),unique(product_id,variation_id,station_id,preparation_sequence)
);
create table public.product_production_steps(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,
 product_id uuid not null references public.products(id) on delete cascade,variation_id uuid,step_order integer not null check(step_order>0),station_id uuid not null references public.kitchen_stations(id) on delete restrict,estimated_duration integer not null default 10 check(estimated_duration>0),can_run_parallel boolean not null default false,dependency_step_id uuid references public.product_production_steps(id) on delete restrict,course text,max_hold_minutes integer not null default 5 check(max_hold_minutes>=0),active boolean not null default true,unique(product_id,variation_id,step_order),check(dependency_step_id is distinct from id)
);
create table public.order_production_plans(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,
 order_id uuid references public.orders(id) on delete cascade,table_order_id uuid references public.table_orders(id) on delete cascade,status text not null default 'planned' check(status in('planned','released','in_progress','partially_ready','ready','completed','cancelled','exception')),target_ready_at timestamptz,generated_at timestamptz not null default now(),priority_score numeric not null default 0,manual_priority text not null default 'normal' check(manual_priority in('normal','high','urgent')),priority_reason text,predicted_ready_at timestamptz,course_control_enabled boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((order_id is not null)::int+(table_order_id is not null)::int=1),unique(order_id),unique(table_order_id)
);
create table public.kitchen_batches(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,station_id uuid not null references public.kitchen_stations(id) on delete restrict,product_id uuid references public.products(id) on delete set null,variation_id uuid,quantity integer not null check(quantity>0),status text not null default 'planned' check(status in('planned','in_progress','completed','cancelled')),started_at timestamptz,completed_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now()
);
create table public.kitchen_tasks(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,
 production_plan_id uuid not null references public.order_production_plans(id) on delete cascade,order_id uuid references public.orders(id) on delete cascade,table_order_id uuid references public.table_orders(id) on delete cascade,order_item_id uuid references public.order_items(id) on delete cascade,table_order_item_id uuid references public.table_order_items(id) on delete cascade,station_id uuid not null references public.kitchen_stations(id) on delete restrict,production_step_id uuid references public.product_production_steps(id) on delete set null,
 status text not null default 'queued' check(status in('queued','waiting_dependency','ready_to_start','in_progress','paused','completed','cancelled','exception')),priority numeric not null default 0,priority_factors jsonb not null default '{}',queued_at timestamptz not null default now(),fire_at timestamptz,started_at timestamptz,estimated_ready_at timestamptz,completed_at timestamptz,assigned_employee_id uuid references public.custom_staff_members(id) on delete set null,batch_id uuid references public.kitchen_batches(id) on delete set null,idempotency_key text,version bigint not null default 1,pause_reason text,exception_type text check(exception_type is null or exception_type in('ingredient_missing','equipment_issue','remake','quality_issue','order_change','other')),remake_of_task_id uuid references public.kitchen_tasks(id),remake_reason text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((order_id is not null)::int+(table_order_id is not null)::int=1),unique(store_id,idempotency_key)
);
create table public.kitchen_task_dependencies(task_id uuid not null references public.kitchen_tasks(id) on delete cascade,depends_on_task_id uuid not null references public.kitchen_tasks(id) on delete cascade,primary key(task_id,depends_on_task_id),check(task_id<>depends_on_task_id));
create table public.kitchen_equipment(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,station_id uuid not null references public.kitchen_stations(id) on delete cascade,name text not null,type text not null default 'custom',capacity numeric not null default 1 check(capacity>=0),status text not null default 'available' check(status in('available','busy','maintenance','unavailable')),updated_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.station_routing_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,product_id uuid references public.products(id) on delete cascade,source_station_id uuid not null references public.kitchen_stations(id) on delete cascade,target_station_id uuid not null references public.kitchen_stations(id) on delete cascade,rule_type text not null default 'overflow' check(rule_type in('overflow','secondary','manual_only')),load_threshold_percent integer not null default 90 check(load_threshold_percent between 1 and 100),automatic boolean not null default false,active boolean not null default true,check(source_station_id<>target_station_id));
create table public.expedition_checks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,production_plan_id uuid not null references public.order_production_plans(id) on delete cascade,check_key text not null,required boolean not null default false,checked boolean not null default false,checked_by uuid references auth.users(id),checked_at timestamptz,unique(production_plan_id,check_key));
create table public.kitchen_exceptions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,task_id uuid references public.kitchen_tasks(id) on delete cascade,exception_type text not null,details text,status text not null default 'open' check(status in('open','resolved','cancelled')),inventory_waste_movement_id uuid references public.inventory_movements(id) on delete set null,reported_by uuid references auth.users(id),resolved_by uuid references auth.users(id),created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.kitchen_change_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,order_id uuid references public.orders(id) on delete cascade,table_order_id uuid references public.table_orders(id) on delete cascade,requested_change jsonb not null,status text not null default 'pending' check(status in('pending','accepted','rejected','applied')),reason text,requested_by uuid references auth.users(id),decided_by uuid references auth.users(id),created_at timestamptz not null default now(),decided_at timestamptz);
create table public.kitchen_audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,actor_user_id uuid references auth.users(id),event_type text not null,entity_type text not null,entity_id uuid,reason text,before_state jsonb,after_state jsonb,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.kitchen_outbox(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid not null,event_key text not null,event_type text not null,aggregate_type text not null,aggregate_id uuid not null,payload jsonb not null default '{}',status text not null default 'pending' check(status in('pending','processing','published','failed')),attempts integer not null default 0,next_attempt_at timestamptz not null default now(),created_at timestamptz not null default now(),published_at timestamptz,unique(store_id,event_key));

create table public.analytics_dim_kitchen_station(station_id uuid primary key,organization_id uuid not null,store_id uuid not null,name text not null,station_type text not null,active boolean not null,source_updated_at timestamptz not null,loaded_at timestamptz not null default now());
create table public.analytics_dim_kitchen_equipment(equipment_id uuid primary key,organization_id uuid not null,store_id uuid not null,station_id uuid not null,name text not null,type text not null,status text not null,source_updated_at timestamptz not null,loaded_at timestamptz not null default now());
create table public.analytics_dim_production_step(step_id uuid primary key,organization_id uuid not null,store_id uuid not null,product_id uuid not null,station_id uuid not null,step_order integer not null,estimated_duration integer not null,loaded_at timestamptz not null default now());
create table public.analytics_fact_kitchen_tasks(task_id uuid primary key,organization_id uuid not null,store_id uuid not null,station_id uuid not null,order_id uuid,status text not null,queued_at timestamptz,started_at timestamptz,completed_at timestamptz,wait_minutes numeric,prep_minutes numeric,late boolean not null default false,remake boolean not null default false,loaded_at timestamptz not null default now());
create table public.analytics_fact_kitchen_batches(batch_id uuid primary key,organization_id uuid not null,store_id uuid not null,station_id uuid not null,product_id uuid,quantity integer not null,status text not null,started_at timestamptz,completed_at timestamptz,loaded_at timestamptz not null default now());
create table public.analytics_fact_station_load(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid not null,station_id uuid not null,bucket_at timestamptz not null,current_load integer not null,capacity integer not null,utilization_percent numeric not null,loaded_at timestamptz not null default now(),unique(station_id,bucket_at));
create table public.analytics_fact_kitchen_exceptions(exception_id uuid primary key,organization_id uuid not null,store_id uuid not null,station_id uuid,exception_type text not null,status text not null,created_at timestamptz not null,resolved_at timestamptz,loaded_at timestamptz not null default now());
create table public.analytics_fact_order_production(plan_id uuid primary key,organization_id uuid not null,store_id uuid not null,order_id uuid,status text not null,target_ready_at timestamptz,predicted_ready_at timestamptz,ready_at timestamptz,expedition_wait_minutes numeric,loaded_at timestamptz not null default now());

insert into public.analytics_metric_catalog(metric_key,name,description,formula,source_of_truth,grain,owner_label,refresh_frequency,unit,evidence_class,sensitive,allowed_dimensions) values
