create index kitchen_tasks_queue_idx on public.kitchen_tasks(store_id,station_id,status,priority desc,fire_at,queued_at) include(order_id,order_item_id,estimated_ready_at);
create index kitchen_tasks_plan_idx on public.kitchen_tasks(production_plan_id,status);
create index order_production_active_idx on public.order_production_plans(store_id,status,target_ready_at);
create index kitchen_outbox_pending_idx on public.kitchen_outbox(status,next_attempt_at);
create index kitchen_audit_scope_idx on public.kitchen_audit_events(store_id,created_at desc);

do $$ declare t text; begin foreach t in array array['kitchen_stations','product_station_assignments','product_production_steps','order_production_plans','kitchen_batches','kitchen_tasks','kitchen_task_dependencies','kitchen_equipment','station_routing_rules','expedition_checks','kitchen_exceptions','kitchen_change_requests','kitchen_audit_events','kitchen_outbox'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on table public.%I from anon,authenticated',t);execute format('grant select,insert,update,delete on table public.%I to authenticated',t);end loop;end $$;
do $$ declare t text; begin foreach t in array array['analytics_dim_kitchen_station','analytics_dim_kitchen_equipment','analytics_dim_production_step','analytics_fact_kitchen_tasks','analytics_fact_kitchen_batches','analytics_fact_station_load','analytics_fact_kitchen_exceptions','analytics_fact_order_production'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on table public.%I from anon,authenticated',t);execute format('grant select on table public.%I to authenticated',t);end loop;end $$;
do $$ declare t text; begin foreach t in array array['kitchen_stations','product_station_assignments','product_production_steps','order_production_plans','kitchen_batches','kitchen_tasks','kitchen_equipment','station_routing_rules','expedition_checks','kitchen_exceptions','kitchen_change_requests','kitchen_audit_events','kitchen_outbox'] loop execute format('create policy %I on public.%I for all to authenticated using(private.has_role(store_id,array[''owner'',''manager'',''kitchen'']::public.member_role[])) with check(private.has_role(store_id,array[''owner'',''manager'',''kitchen'']::public.member_role[]))',t||'_operations',t);end loop;end $$;
create policy kitchen_task_dependencies_operations on public.kitchen_task_dependencies for all to authenticated using(exists(select 1 from public.kitchen_tasks t where t.id=task_id and private.has_role(t.store_id,array['owner','manager','kitchen']::public.member_role[]))) with check(exists(select 1 from public.kitchen_tasks t where t.id=task_id and private.has_role(t.store_id,array['owner','manager','kitchen']::public.member_role[])));
do $$ declare t text; begin foreach t in array array['analytics_dim_kitchen_station','analytics_dim_kitchen_equipment','analytics_dim_production_step','analytics_fact_kitchen_tasks','analytics_fact_kitchen_batches','analytics_fact_station_load','analytics_fact_kitchen_exceptions','analytics_fact_order_production'] loop execute format('create policy %I on public.%I for select to authenticated using(exists(select 1 from public.organization_members om where om.organization_id=%I.organization_id and om.user_id=(select auth.uid()) and om.active=true))',t||'_read',t,t);end loop;end $$;

create or replace function public.validate_production_step_cycle() returns trigger language plpgsql set search_path='' as $$declare cursor_id uuid:=new.dependency_step_id;begin while cursor_id is not null loop if cursor_id=new.id then raise exception 'Dependência cíclica não permitida.';end if;select dependency_step_id into cursor_id from public.product_production_steps where id=cursor_id;end loop;return new;end$$;
create trigger product_step_cycle_guard before insert or update on public.product_production_steps for each row execute function public.validate_production_step_cycle();

create or replace function public.kitchen_task_transition(requested_task_id uuid,requested_status text,requested_idempotency_key text,requested_reason text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare t public.kitchen_tasks;old_state jsonb;actor uuid:=(select auth.uid());begin if actor is null then raise exception 'Autenticação necessária.';end if;select * into t from public.kitchen_tasks where id=requested_task_id for update;if not found or not private.has_role(t.store_id,array['owner','manager','kitchen']::public.member_role[]) then raise exception 'Tarefa não encontrada.';end if;if requested_idempotency_key is not null and t.metadata->>'last_action_key'=requested_idempotency_key then return jsonb_build_object('task',to_jsonb(t),'idempotent',true);end if;if t.status in('completed','cancelled') and requested_status<>t.status then raise exception 'Status final não pode regredir.';end if;if requested_status='completed' and t.started_at is null then raise exception 'Item precisa ser iniciado por evento operacional real.';end if;old_state:=to_jsonb(t);update public.kitchen_tasks set status=requested_status,started_at=case when requested_status='in_progress' then coalesce(started_at,now()) else started_at end,completed_at=case when requested_status='completed' then coalesce(completed_at,now()) else completed_at end,pause_reason=case when requested_status in('paused','exception') then requested_reason else pause_reason end,metadata=metadata||jsonb_build_object('last_action_key',requested_idempotency_key),version=version+1,updated_at=now() where id=t.id returning * into t;insert into public.kitchen_audit_events(organization_id,store_id,actor_user_id,event_type,entity_type,entity_id,reason,before_state,after_state) values(t.organization_id,t.store_id,actor,'task_'||requested_status,'kitchen_task',t.id,requested_reason,old_state,to_jsonb(t));insert into public.kitchen_outbox(organization_id,store_id,event_key,event_type,aggregate_type,aggregate_id,payload) values(t.organization_id,t.store_id,coalesce(requested_idempotency_key,gen_random_uuid()::text),'kitchen.task.'||requested_status,'kitchen_task',t.id,to_jsonb(t)) on conflict(store_id,event_key) do nothing;return jsonb_build_object('task',to_jsonb(t),'idempotent',false);end$$;
revoke all on function public.kitchen_task_transition(uuid,text,text,text) from public,anon;grant execute on function public.kitchen_task_transition(uuid,text,text,text) to authenticated;

do $$ begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='kitchen_tasks') then alter publication supabase_realtime add table public.kitchen_tasks;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='order_production_plans') then alter publication supabase_realtime add table public.order_production_plans;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='kitchen_batches') then alter publication supabase_realtime add table public.kitchen_batches;end if;end$$;
